<body class="pagina-solicitacao-privacidade"><main class="pagina-acompanhamento"><article class="cartao-acompanhamento" aria-labelledby="privacyTitle"><span class="sobretitulo">LGPD E PRIVACIDADE</span><h1 id="privacyTitle">Solicitação do titular</h1><p id="privacyHelp">Envie uma solicitação relacionada aos dados tratados por <?= e($store['name']) ?>. A identidade poderá ser confirmada antes do atendimento.</p><?php if($flash):?><div class="aviso <?= e($flash[0]) ?>" role="<?= $flash[0]==='error'?'alert':'status' ?>"><?= e($flash[1]) ?></div><?php endif;?><form class="formulario" method="post" aria-describedby="privacyHelp"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Nome completo<input name="name" maxlength="160" autocomplete="name" required></label><label>E-mail<input type="email" name="email" maxlength="190" autocomplete="email" required></label><label>Solicitação<select name="request_type" required><option value="access">Acesso aos dados</option><option value="correction">Correção</option><option value="deletion">Exclusão</option><option value="portability">Portabilidade</option><option value="revocation">Revogação de consentimento</option></select></label><label>Detalhes<textarea name="notes" maxlength="5000" aria-describedby="notesHelp"></textarea></label><small id="notesHelp">Não informe senhas, dados completos de pagamento ou outros segredos.</small><?= turnstile_widget('privacy_request') ?><button class="botao primario" type="submit">Registrar solicitação</button></form></article></main><?= turnstile_script() ?></body></html>

